/* glass shapes beyond spCocktail: shot|balloon|margarita|sling|hurricane|mule|julep|toddy|tiki. origin = foot. o: {s, salt, gar, ice, mint, cream} */
const spGlass=(x,y,type,col,o)=>{ o=o||{}; col=col||"#e9dc8c"; let g="";
  if(type==="shot") g=`<path d="M-9 -13H9L8 0H-8Z" fill="${col}"/><path d="M-10 -26H10L8 1H-8Z" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/>`;
  if(type==="balloon") g=`<path d="M-21 -26Q-19 -12 0 -12Q19 -12 21 -26Z" fill="${col}" opacity=".9"/><path d="M-10 -58Q-26 -46 -22 -28Q-18 -12 0 -12Q18 -12 22 -28Q26 -46 10 -58" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/><path d="M0 -12V-1M-12 0H12" stroke="#e8dccf" stroke-width="2" stroke-linecap="round"/>`;
  if(type==="margarita") g=`<path d="M-22 -48Q-20 -41 -10 -39Q-8 -31 0 -29Q8 -31 10 -39Q20 -41 22 -48Z" fill="${col}" opacity=".9"/><path d="M-24 -50Q-22 -40 -10 -38Q-8 -30 0 -28Q8 -30 10 -38Q22 -40 24 -50" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/><path d="M0 -28V-1M-11 0H11" stroke="#e8dccf" stroke-width="2" stroke-linecap="round"/>${o.salt?`<path d="M-24 -50H24" stroke="#fff" stroke-width="2.6" stroke-dasharray="1.5 1.5"/>`:""}`;
  if(type==="sling") g=`<path d="M-11 -60L-7 -13Q0 -9 7 -13L11 -60Z" fill="${col}" opacity=".88"/><path d="M-12 -72L-7 -12Q0 -8 7 -12L12 -72" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/><path d="M0 -9V-1M-9 0H9" stroke="#e8dccf" stroke-width="2" stroke-linecap="round"/>`;
  if(type==="hurricane") g=`<path d="M-11 -58Q-12 -48 -15 -40Q-20 -20 -6 -14Q0 -12 6 -14Q20 -20 15 -40Q12 -48 11 -58Z" fill="${col}" opacity=".9"/><path d="M-11 -72Q-9 -56 -15 -40Q-20 -20 -6 -14Q0 -12 6 -14Q20 -20 15 -40Q9 -56 11 -72" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/><path d="M0 -12V-1M-10 0H10" stroke="#e8dccf" stroke-width="2" stroke-linecap="round"/>`;
  if(type==="mule") g=`<path d="M14 -32Q27 -30 27 -21Q27 -11 14 -10" stroke="#9a4f22" stroke-width="4" fill="none"/><path d="M-15 -42H15V-2Q15 0 13 0H-13Q-15 0 -15 -2Z" fill="url(#spcu)" stroke="#5a2c12"/>${[[-8,-30],[2,-22],[8,-34],[-4,-12],[7,-10]].map(([a,b])=>`<circle cx="${a}" cy="${b}" r="1.6" fill="rgba(255,220,180,.35)"/>`).join("")}`;
  if(type==="julep") g=`<path d="M-15 -44H15L12 -4Q12 0 8 0H-8Q-12 0 -12 -4Z" fill="url(#fst)" stroke="#5c646b"/><path d="M-15 -44Q-8 -54 0 -50Q8 -56 15 -44Z" fill="#eef8fc" stroke="#bfe6f6"/>${fLeaf(-3,-52,.6,-20,"#4f9a3a")+fLeaf(5,-54,.55,25,"#5eae44")}<path d="M-10 -36V-8M-4 -36V-8M2 -36V-8M8 -36V-8" stroke="rgba(255,255,255,.35)" stroke-width="1"/>`;
  if(type==="toddy") g=`<path d="M12 -38Q24 -36 24 -28Q24 -20 11 -18" stroke="#e8dccf" stroke-width="2.4" fill="none"/><path d="M-11 -36H11L10 -12H-10Z" fill="${col}"/><path d="M-12 -40H12L10 -12H-10Z" fill="#f3ead6"/><path d="M-12 -46H12L10 -10H-10Z" fill="url(#spgl)" stroke="#e8dccf" stroke-width="1.4"/><path d="M0 -10V-2M-10 0H10" stroke="#e8dccf" stroke-width="2" stroke-linecap="round"/>${spVapour(0,-50,2,16)}`;
  if(type==="tiki") g=`<path d="M-14 -50H14V-2Q14 0 12 0H-12Q-14 0 -14 -2Z" fill="#8a5a33" stroke="#4e321c"/><path d="M-10 -40h7M3 -40h7" stroke="#2a1b17" stroke-width="3"/><path d="M-8 -30Q0 -26 8 -30M-9 -16H9" stroke="#2a1b17" stroke-width="2.4" fill="none"/><path d="M-2 -36L0 -26L2 -36" stroke="#2a1b17" stroke-width="1.6" fill="none"/>${fLeaf(8,-52,.7,30,"#4f9a3a")}`;
  if(o.gar) g+=spCitrus(type==="hurricane"||type==="sling"?11:16,type==="hurricane"||type==="sling"?-72:-44,6,o.gar);
  return spG(x,y,o.s,g); };
